        let m1 = multiply(self.components[1], rhs.c1);
        let m2 = multiply(self.components[2], rhs.c0.add(rhs.c1));
        QM31 {
            c0: m0.add(mul_by_r(m1)),
            c1: m2.sub(m0).sub(m1),
        }
